INSERT INTO permissions(name,guard_name,description) VALUES ('question_groups.view','web','Melihat kelompok soal'),('question_groups.manage','web','Mengelola kelompok soal') ON DUPLICATE KEY UPDATE description=VALUES(description);
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='superadmin' AND p.name IN ('question_groups.view','question_groups.manage');
